-- Requires Oracle Database 23ai or later (multi-row INSERT ... VALUES; COMPATIBLE 23 or later). Verified on Oracle AI Database 26ai Free 23.26.3 with SQL*Plus 23.26.3.
-- Load it into an EMPTY schema that may create tables and sequences (identity columns) and has a quota, with SQL*Plus, from the file:
--   NLS_LANG=.AL32UTF8 sqlplus -L -S <user>/<password>@<service> @<file>.sql
-- The file is UTF-8 without a byte order mark. The database character set must be AL32UTF8 and the client NLS_LANG must say UTF-8: the first statement checks both
-- and stops the load when either differs (a client in another character set would store the text of this file damaged).
-- No data in this file can start a line, so a line is never a SQL*Plus command or a '/'; no line is longer than 2300 characters (SQL*Plus refuses 2,499 in older versions).
-- The script sets DEFINE OFF (a & in a value is no substitution variable) and stops at the first error (WHENEVER SQLERROR EXIT FAILURE ROLLBACK).
-- Oracle commits every DDL statement: the script is NOT one transaction, and a failed load leaves the tables it had created (drop them, and the marker, before loading again).
-- The first statement creates the table _demodb_import and fails when it exists (a second load stops there); the last one counts every table's rows, keys, checks and indexes in the catalog
-- and writes the marker row in one PL/SQL block that raises first when a count is wrong: a row there means every table holds its rows and has its keys, checks and indexes,
-- whatever the client did after an error (it does not compare the text of a default or of a check).
-- DROP TABLE "_demodb_import" removes the marker once you no longer need it.
-- The empty text is NULL in Oracle: a column that holds an empty text is created without NOT NULL and holds NULL there. Text comparison is binary by default (NLS_COMP=BINARY).
-- A unique key over several columns treats NULLs as equal in Oracle, unlike SQLite: such a key is written as a unique function-based index.
-- Tables (11): authors, publishers, titles, titleauthor, stores, sales, roysched, discounts, jobs, pub_info, employee
--
-- 8 thing(s) are not carried exactly:
-- [collation-not-carried] authors.check #1: a comparison or pattern of text in this check follows the NLS_COMP and NLS_SORT of the session that writes a row (BINARY, like SQLite, unless it changes them); the script loads with BINARY
-- [collation-not-carried] authors.check #2: a comparison or pattern of text in this check follows the NLS_COMP and NLS_SORT of the session that writes a row (BINARY, like SQLite, unless it changes them); the script loads with BINARY
-- [values-normalized] discounts.discount: 2 REAL and 1 INTEGER value(s) share one NUMBER(4,2) column: SQLite keeps them apart (5 and 5.0), NUMBER(4,2) does not; each REAL is written as the exact decimal of its shortest spelling, for example 10.5
-- [collation-not-carried] employee.check #1: a comparison or pattern of text in this check follows the NLS_COMP and NLS_SORT of the session that writes a row (BINARY, like SQLite, unless it changes them); the script loads with BINARY
-- [values-normalized] employee.minit: 10 empty value(s) become NULL, because Oracle has no empty text
-- [collation-not-carried] publishers.check #1: a comparison or pattern of text in this check follows the NLS_COMP and NLS_SORT of the session that writes a row (BINARY, like SQLite, unless it changes them); the script loads with BINARY
-- [values-normalized] titles.price: 14 REAL and 2 INTEGER value(s) share one NUMBER(4,2) column: SQLite keeps them apart (5 and 5.0), NUMBER(4,2) does not; each REAL is written as the exact decimal of its shortest spelling, for example 19.99
-- [view-not-carried] titleview: views are written in the SQL dialect of their engine and are not translated across engines

SET DEFINE OFF
SET ESCAPE OFF
SET CMDSEP OFF
SET SQLTERMINATOR ';'
SET SQLPREFIX #
SET ECHO OFF
SET FEEDBACK OFF
SET VERIFY OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
ALTER SESSION SET NLS_COMP = BINARY NLS_SORT = BINARY;
DECLARE
  ver VARCHAR2(100);
  compat VARCHAR2(100);
  cs VARCHAR2(100);
BEGIN
  IF DBMS_DB_VERSION.VERSION < 23 THEN
    RAISE_APPLICATION_ERROR(-20001, 'this script needs Oracle Database 23ai or later (multi-row INSERT ... VALUES)');
  END IF;
  DBMS_UTILITY.DB_VERSION(ver, compat);
  IF TO_NUMBER(REGEXP_SUBSTR(compat, '^[0-9]+')) < 23 THEN
    RAISE_APPLICATION_ERROR(-20001, 'COMPATIBLE is ' || compat || ': this script needs COMPATIBLE 23 or later');
