CREATE TABLE "_demodb_import" ("dataset" VARCHAR2(4000 BYTE), "edition" VARCHAR2(4000 BYTE), "source_sha256" VARCHAR2(64 CHAR) NOT NULL, "datatug_version" VARCHAR2(4000 BYTE), "tables_count" NUMBER(10,0) NOT NULL, "rows_count" NUMBER(19,0) NOT NULL);

CREATE TABLE "authors" (
  "au_id" VARCHAR2(11 CHAR) NOT NULL,
  "au_lname" VARCHAR2(40 CHAR) NOT NULL,
  "au_fname" VARCHAR2(20 CHAR) NOT NULL,
  "phone" VARCHAR2(12 CHAR) DEFAULT ('UNKNOWN') NOT NULL,
  "address" VARCHAR2(40 CHAR),
  "city" VARCHAR2(20 CHAR),
  "state" VARCHAR2(2 CHAR),
  "zip" VARCHAR2(5 CHAR),
  "contract" NUMBER(19,0) NOT NULL,
  PRIMARY KEY ("au_id")
);
CREATE TABLE "publishers" (
  "pub_id" VARCHAR2(4 CHAR) NOT NULL,
  "pub_name" VARCHAR2(40 CHAR),
  "city" VARCHAR2(20 CHAR),
  "state" VARCHAR2(2 CHAR),
  "country" VARCHAR2(30 CHAR) DEFAULT ('USA'),
  PRIMARY KEY ("pub_id")
);
CREATE TABLE "titles" (
  "title_id" VARCHAR2(6 CHAR) NOT NULL,
  "title" VARCHAR2(80 CHAR) NOT NULL,
  "type" VARCHAR2(12 CHAR) DEFAULT ('UNDECIDED') NOT NULL,
  "pub_id" VARCHAR2(4 CHAR),
  "price" NUMBER(4,2),
  "advance" NUMBER(5,0),
  "royalty" NUMBER(19,0),
  "ytd_sales" NUMBER(19,0),
  "notes" VARCHAR2(200 CHAR),
  "pubdate" VARCHAR2(4000 BYTE) DEFAULT ('2000-01-01') NOT NULL,
  PRIMARY KEY ("title_id")
);
CREATE TABLE "titleauthor" (
  "au_id" VARCHAR2(11 CHAR) NOT NULL,
  "title_id" VARCHAR2(6 CHAR) NOT NULL,
  "au_ord" NUMBER(19,0),
  "royaltyper" NUMBER(19,0),
  PRIMARY KEY ("au_id", "title_id")
);
CREATE TABLE "stores" (
  "stor_id" VARCHAR2(4 CHAR) NOT NULL,
  "stor_name" VARCHAR2(40 CHAR),
  "stor_address" VARCHAR2(40 CHAR),
  "city" VARCHAR2(20 CHAR),
  "state" VARCHAR2(2 CHAR),
  "zip" VARCHAR2(5 CHAR),
  PRIMARY KEY ("stor_id")
);
CREATE TABLE "sales" (
  "stor_id" VARCHAR2(4 CHAR) NOT NULL,
  "ord_num" VARCHAR2(20 CHAR) NOT NULL,
  "ord_date" VARCHAR2(4000 BYTE) NOT NULL,
  "qty" NUMBER(19,0) NOT NULL,
  "payterms" VARCHAR2(12 CHAR) NOT NULL,
  "title_id" VARCHAR2(6 CHAR) NOT NULL,
  PRIMARY KEY ("stor_id", "ord_num", "title_id")
);
CREATE TABLE "roysched" (
  "title_id" VARCHAR2(6 CHAR),
  "lorange" NUMBER(19,0),
  "hirange" NUMBER(19,0),
  "royalty" NUMBER(19,0)
);
CREATE TABLE "discounts" (
  "discounttype" VARCHAR2(40 CHAR) NOT NULL,
  "stor_id" VARCHAR2(4 CHAR),
  "lowqty" NUMBER(19,0),
  "highqty" NUMBER(19,0),
  "discount" NUMBER(4,2) NOT NULL
);
CREATE TABLE "jobs" (
  "job_id" NUMBER(19,0) GENERATED BY DEFAULT AS IDENTITY,
  "job_desc" VARCHAR2(50 CHAR) DEFAULT ('New Position - title not formalized yet') NOT NULL,
  "min_lvl" NUMBER(19,0) NOT NULL,
  "max_lvl" NUMBER(19,0) NOT NULL,
  PRIMARY KEY ("job_id")
);
CREATE TABLE "pub_info" (
  "pub_id" VARCHAR2(4 CHAR) NOT NULL,
  "logo" BLOB,
  "pr_info" CLOB,
  PRIMARY KEY ("pub_id")
);
CREATE TABLE "employee" (
  "emp_id" VARCHAR2(10 CHAR) NOT NULL,
  "fname" VARCHAR2(20 CHAR) NOT NULL,
  "minit" VARCHAR2(1 CHAR),
  "lname" VARCHAR2(30 CHAR) NOT NULL,
  "job_id" NUMBER(19,0) DEFAULT (1) NOT NULL,
  "job_lvl" NUMBER(19,0) DEFAULT (10),
  "pub_id" VARCHAR2(4 CHAR) DEFAULT ('9952') NOT NULL,
  "hire_date" VARCHAR2(4000 BYTE) DEFAULT ('2000-01-01') NOT NULL,
  PRIMARY KEY ("emp_id")
);
