CREATE INDEX "roysched_titleidind" ON "roysched" ("title_id");
CREATE INDEX "employee_employee_ind" ON "employee" ("lname", "fname", "minit");
ALTER TABLE "authors" ADD CHECK (REGEXP_LIKE("au_id", '^[0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][0-9][0-9]$', 'cn'));
ALTER TABLE "authors" ADD CHECK (REGEXP_LIKE("zip", '^[0-9][0-9][0-9][0-9][0-9]$', 'cn'));
ALTER TABLE "publishers" ADD CHECK ("pub_id" IN ( '1389' , '0736' , '0877' , '1622' , '1756' ) OR REGEXP_LIKE("pub_id", '^99[0-9][0-9]$', 'cn'));
ALTER TABLE "jobs" ADD CHECK ("min_lvl" >= 10);
ALTER TABLE "jobs" ADD CHECK ("max_lvl" <= 250);
ALTER TABLE "employee" ADD CHECK (REGEXP_LIKE("emp_id", '^[A-Z][A-Z][A-Z][1-9][0-9][0-9][0-9][0-9][FM]$', 'cn') OR REGEXP_LIKE("emp_id", '^[A-Z]-[A-Z][1-9][0-9][0-9][0-9][0-9][FM]$', 'cn'));
ALTER TABLE "titles" ADD FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id");
ALTER TABLE "titleauthor" ADD FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id");
ALTER TABLE "titleauthor" ADD FOREIGN KEY ("au_id") REFERENCES "authors" ("au_id");
ALTER TABLE "sales" ADD FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id");
ALTER TABLE "sales" ADD FOREIGN KEY ("stor_id") REFERENCES "stores" ("stor_id");
ALTER TABLE "roysched" ADD FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id");
ALTER TABLE "discounts" ADD FOREIGN KEY ("stor_id") REFERENCES "stores" ("stor_id");
ALTER TABLE "pub_info" ADD FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id");
ALTER TABLE "employee" ADD FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id");
ALTER TABLE "employee" ADD FOREIGN KEY ("job_id") REFERENCES "jobs" ("job_id");
COMMIT;
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM "authors";
  IF n <> 23 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table authors does not hold 23 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "publishers";
  IF n <> 8 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table publishers does not hold 8 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "titles";
  IF n <> 18 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table titles does not hold 18 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "titleauthor";
  IF n <> 25 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table titleauthor does not hold 25 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "stores";
  IF n <> 6 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table stores does not hold 6 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "sales";
  IF n <> 21 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table sales does not hold 21 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "roysched";
  IF n <> 86 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table roysched does not hold 86 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "discounts";
  IF n <> 3 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table discounts does not hold 3 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "jobs";
  IF n <> 14 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table jobs does not hold 14 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "pub_info";
  IF n <> 8 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table pub_info does not hold 8 rows'); END IF;
  SELECT COUNT(*) INTO n FROM "employee";
  IF n <> 43 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: table employee does not hold 43 rows'); END IF;
  SELECT COUNT(*) INTO n FROM user_constraints WHERE table_name IN ('authors', 'publishers', 'titles', 'titleauthor', 'stores', 'sales', 'roysched', 'discounts', 'jobs', 'pub_info', 'employee') AND constraint_type IN ('P','U','R') AND status = 'ENABLED' AND validated = 'VALIDATED';
  IF n <> 19 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: '||n||' keys in the catalog, not the 19 of the tables authors to employee'); END IF;
  SELECT COUNT(*) INTO n FROM user_constraints WHERE table_name IN ('authors', 'publishers', 'titles', 'titleauthor', 'stores', 'sales', 'roysched', 'discounts', 'jobs', 'pub_info', 'employee') AND constraint_type = 'C' AND status = 'ENABLED' AND validated = 'VALIDATED';
  IF n <> 38 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: '||n||' checks in the catalog, not the 38 of the tables authors to employee'); END IF;
  SELECT COUNT(*) INTO n FROM user_indexes WHERE table_name IN ('authors', 'publishers', 'titles', 'titleauthor', 'stores', 'sales', 'roysched', 'discounts', 'jobs', 'pub_info', 'employee') AND index_type <> 'LOB';
  IF n <> 16 THEN RAISE_APPLICATION_ERROR(-20000, 'the load is incomplete: '||n||' indexes in the catalog, not the 16 of the tables authors to employee'); END IF;
  INSERT INTO "_demodb_import" VALUES
('pubs','DemoDB contract edition, identical to the SQLite/CSV/JSON','b45b08b7c06441cc0b138b031ea5bd32bd5866aebf874c89d2ebf7fc6abb3691','v0.103.4',11,255);
  COMMIT;
END;
